{
  "checks": [
    {
      "claim_id": "claim.894541a0364011077a8c8c96",
      "candidate_id": "node.2a6321b4ce90763bf0be564e",
      "source_support": {
        "status": "SUPPORTED",
        "evidence": [
          {
            "unit_id": "db43e253bea18.u10.2239",
            "quote": "SFC-authorised funds without guaranteed features are required to highlight in their offering documents that they do not have these features and that investors may not get back the principal of their investment1."
          },
          {
            "unit_id": "db43e253bea18.u27.7511",
            "quote": "1 Pursuant to 6.4 of the Overarching Principles Section as set out in the SFC Handbook for Unit Trusts and Mutual Funds, Investment-Linked Assurance Schemes and Unlisted Structured Investment Products, offering documents of an SFC-authorised fund shall contain the information necessary for investors to be able to make an informed judgement of the investment whilst all key features and risks of the fund shall be highlighted prominently in a succinct manner for investors."
          }
        ],
        "rationale": "The disclosure duty is expressly stated. Footnote 1 is supplied and identifies its foundation; the claim's recorded uncertainty about that footnote is stale. The claim captures one part of the disclosure requirement."
      },
      "question_relation": {
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION",
        "question_hash": "992266faf576fb875514dcce2dc093509ff17576471836fad7b17e5bf08d265a",
        "evidence": [
          {
            "unit_id": "db43e253bea18.u13.2987",
            "quote": "Paragraph 3.11 of the Code of Conduct provides that distributors should not offer any gifts (other than a discount of fees or charges) in promoting a specific investment product or a particular type of investment product to a client."
          }
        ],
        "rationale": "The typed question concerns whether one benefit component is caught by the gift restriction. A fund's offering-document disclosure duty is separate, although it supplies context for guaranteed-return arrangements."
      },
      "executable_correspondence": {
        "status": "NOT_APPLICABLE",
        "representation_quotes": [
          "Scope: all of these conditions hold: [the fact offeror_is_distributor; the fact component_offered_to_client]",
          "Result: all of these conditions hold: [the fact component_is_gift; it is not the case that [the fact component_is_fee_or_charge_discount]; at least one of these conditions holds: [the fact component_promotes_specific_product; the fact component_linked_to_product_type]]"
        ],
        "rationale": "The executable expression tests component-level gift conditions. Its lack of an offering-document disclosure test is not an omission relative to this typed question."
      },
      "authority": {
        "status": "NONE_DECLARED",
        "dependency_ids": [],
        "rationale": "The circular and supplied footnote support this narrow source claim without an additional external dependency. Independent verification of the underlying Handbook provision remains separate."
      },
      "followup_questions": []
    },
